CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,profile TEXT NOT NULL DEFAULT '{}',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(th TEXT PRIMARY KEY,uid INTEGER NOT NULL,exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS state(uid INTEGER PRIMARY KEY,data TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pros(uid INTEGER PRIMARY KEY,name TEXT,roles TEXT,created INTEGER);
CREATE TABLE IF NOT EXISTS links(pro INTEGER NOT NULL,client INTEGER NOT NULL,scope TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'on',created INTEGER,PRIMARY KEY(pro,client));
CREATE TABLE IF NOT EXISTS invites(code TEXT PRIMARY KEY,pro INTEGER NOT NULL,scope TEXT NOT NULL,label TEXT,created INTEGER,used_by INTEGER,used_at INTEGER);
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT,pro INTEGER NOT NULL,client INTEGER NOT NULL,dir TEXT NOT NULL,kind TEXT,text TEXT,created INTEGER,seen INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS push_subs(endpoint TEXT PRIMARY KEY,uid INTEGER NOT NULL,p256dh TEXT,auth TEXT,created INTEGER);
